# name: monotone_order_shared_digit_contrast
# description: Among 3-example sets whose examples all share a last digit, yes rate of non-example targets lacking that digit for sets shown in monotone (sorted ascending/descending) order minus sets shown in non-monotone order; observed above null means presentation order (an orderly sequence) loosens the "ends in d" rule, which the order-blind model cannot produce (below null means the reverse).

def test_statistic(df):
    d = df[["number_set", "target", "rating"]].copy()
    d["target"] = d["target"].astype(int)
    mono, non = [], []
    for s, g in d.groupby("number_set"):
        ex = [int(x) for x in s.split(",")]
        if len(ex) != 3 or len({e % 10 for e in ex}) != 1:
            continue
        g = g[(g["target"] % 10) != ex[0] % 10]
        if len(g) == 0:
            continue
        is_mono = ex == sorted(ex) or ex == sorted(ex, reverse=True)
        (mono if is_mono else non).append(g["rating"].to_numpy())
    if not mono or not non:
        return 0.0
    return float(np.concatenate(mono).mean() - np.concatenate(non).mean())

# name: partial_last_digit_majority_contrast
# description: For sets where some last digit is shared by >=2 but not all examples, mean over sets of (yes rate of non-example targets ending in that shared digit minus yes rate of other non-example targets); observed above null means people generalize from a feature most (not all) examples share, which the model's all-or-nothing rule consistency under-produces.

def test_statistic(df):
    d = df[["number_set", "target", "rating"]].copy()
    d["target"] = d["target"].astype(int)
    diffs = []
    for s, g in d.groupby("number_set"):
        ex = [int(x) for x in s.split(",")]
        if len(ex) < 3:
            continue
        ld = [e % 10 for e in ex]
        shared = {x for x in ld if ld.count(x) >= 2 and ld.count(x) < len(ex)}
        if not shared:
            continue
        g = g[~g["target"].isin(ex)]
        m = (g["target"] % 10).isin(list(shared))
        if m.sum() == 0 or (~m).sum() == 0:
            continue
        diffs.append(g.loc[m, "rating"].mean() - g.loc[~m, "rating"].mean())
    return float(np.mean(diffs)) if diffs else 0.0

# name: range_boundary_step
# description: Among non-example targets in no small rule (<=25 members) containing all examples, yes rate of targets just inside the example range (within 5 of min or max) minus targets just outside it (within 5 beyond min or max); observed below null means people's generalization falls off more smoothly at the range edge than the model's interval hypotheses (a sharp step) predict, above null means an even sharper edge.
def _rules():
    N = range(1, 101)
    r = {"odd": {n for n in N if n % 2}, "even": {n for n in N if n % 2 == 0},
         "primes": {n for n in N if n > 1 and all(n % a for a in range(2, int(n ** 0.5) + 1))},
         "squares": {n * n for n in range(1, 11)}, "cubes": {n ** 3 for n in range(1, 5)},
         "pow2no32": {2, 4, 8, 16, 64}, "pow2or37": {2, 4, 8, 16, 32, 37, 64}}
    for m in [3, 4, 5, 6, 7, 8, 9, 11, 12]:
        r["mult%d" % m] = set(range(m, 101, m))
    for m in range(2, 11):
        r["pow%d" % m] = {m ** k for k in range(1, 8) if m ** k <= 100}
    for d in range(10):
        r["ends%d" % d] = {n for n in N if n % 10 == d}
        r["contains%d" % d] = {n for n in N if str(d) in str(n)}
    return r

def test_statistic(df):
    R = _rules()
    d = df[["number_set", "target", "rating"]].copy()
    d["target"] = d["target"].astype(int)
    ins, outs = [], []
    for s, g in d.groupby("number_set"):
        ex = [int(x) for x in s.split(",")]
        lo, hi = min(ex), max(ex)
        small = set()
        for c in R.values():
            if len(c) <= 25 and all(e in c for e in ex):
                small |= c
        t = g["target"].to_numpy()
        r = g["rating"].to_numpy()
        ok = ~np.isin(t, ex) & ~np.isin(t, list(small))
        inside = ok & (t >= lo) & (t <= hi) & ((t - lo <= 5) | (hi - t <= 5))
        outside = ok & (((t < lo) & (lo - t <= 5)) | ((t > hi) & (t - hi <= 5)))
        ins.append(r[inside]); outs.append(r[outside])
    a, b = np.concatenate(ins), np.concatenate(outs)
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())

# name: broad_rule_inside_range_member_yes
# description: For sets of >=3 examples whose smallest consistent rule (of the model's 45) is broad (>=25 members, e.g. even, odd, multiples of 3), yes rate of non-example members of that rule lying inside the example range; observed below null means people endorse well-supported members of broad concepts less than the model predicts (a ceiling well below 1), above null means more.
def _rules():
    N = range(1, 101)
    r = {"odd": {n for n in N if n % 2}, "even": {n for n in N if n % 2 == 0},
         "primes": {n for n in N if n > 1 and all(n % a for a in range(2, int(n ** 0.5) + 1))},
         "squares": {n * n for n in range(1, 11)}, "cubes": {n ** 3 for n in range(1, 5)},
         "pow2no32": {2, 4, 8, 16, 64}, "pow2or37": {2, 4, 8, 16, 32, 37, 64}}
    for m in [3, 4, 5, 6, 7, 8, 9, 11, 12]:
        r["mult%d" % m] = set(range(m, 101, m))
    for m in range(2, 11):
        r["pow%d" % m] = {m ** k for k in range(1, 8) if m ** k <= 100}
    for d in range(10):
        r["ends%d" % d] = {n for n in N if n % 10 == d}
        r["contains%d" % d] = {n for n in N if str(d) in str(n)}
    return r

def test_statistic(df):
    R = _rules()
    d = df[["number_set", "target", "rating"]].copy()
    d["target"] = d["target"].astype(int)
    vals = []
    for s, g in d.groupby("number_set"):
        ex = [int(x) for x in s.split(",")]
        if len(ex) < 3:
            continue
        cons = [c for c in R.values() if all(e in c for e in ex)]
        if not cons:
            continue
        best = min(cons, key=len)
        if len(best) < 25:
            continue
        lo, hi = min(ex), max(ex)
        t = g["target"].to_numpy()
        m = np.isin(t, list(best)) & ~np.isin(t, ex) & (t >= lo) & (t <= hi)
        vals.append(g["rating"].to_numpy()[m])
    v = np.concatenate(vals) if vals else np.array([])
    return float(v.mean()) if len(v) else 0.0

# name: contains_digit_only_rule_member_yes
# description: For sets where some "contains digit d" rule includes all examples but no "ends in" rule does (examples do not share a last digit), yes rate of non-example targets containing d; observed below null means the model over-relies on contains-digit concepts (e.g. predicting 8,18,28 for 98,83), above null means people use them more.
def _rules():
    N = range(1, 101)
    r = {"odd": {n for n in N if n % 2}, "even": {n for n in N if n % 2 == 0},
         "primes": {n for n in N if n > 1 and all(n % a for a in range(2, int(n ** 0.5) + 1))},
         "squares": {n * n for n in range(1, 11)}, "cubes": {n ** 3 for n in range(1, 5)},
         "pow2no32": {2, 4, 8, 16, 64}, "pow2or37": {2, 4, 8, 16, 32, 37, 64}}
    for m in [3, 4, 5, 6, 7, 8, 9, 11, 12]:
        r["mult%d" % m] = set(range(m, 101, m))
    for m in range(2, 11):
        r["pow%d" % m] = {m ** k for k in range(1, 8) if m ** k <= 100}
    for d in range(10):
        r["ends%d" % d] = {n for n in N if n % 10 == d}
        r["contains%d" % d] = {n for n in N if str(d) in str(n)}
    return r

def test_statistic(df):
    R = _rules()
    d = df[["number_set", "target", "rating"]].copy()
    d["target"] = d["target"].astype(int)
    vals = []
    for s, g in d.groupby("number_set"):
        ex = [int(x) for x in s.split(",")]
        if len({e % 10 for e in ex}) == 1:
            continue
        digs = [dd for dd in range(10) if all(e in R["contains%d" % dd] for e in ex)]
        if not digs:
            continue
        t = g["target"].astype(str)
        m = np.zeros(len(g), dtype=bool)
        for dd in digs:
            m |= t.str.contains(str(dd)).to_numpy()
        m &= ~g["target"].isin(ex).to_numpy()
        vals.append(g["rating"].to_numpy()[m])
    v = np.concatenate(vals) if vals else np.array([])
    return float(v.mean()) if len(v) else 0.0

# name: far_opposite_parity_unsupported_yes
# description: For sets whose examples all share parity, yes rate of opposite-parity non-example targets lying more than 5 outside the example range and in no small rule (<=25 members, of the model's 45) containing all examples; observed above null means the parity-restricted model now rejects far opposite-parity targets too firmly (people keep a floor), below null means people reject them even more firmly.
def _rules():
    N = range(1, 101)
    r = {"odd": {n for n in N if n % 2}, "even": {n for n in N if n % 2 == 0},
         "primes": {n for n in N if n > 1 and all(n % a for a in range(2, int(n ** 0.5) + 1))},
         "squares": {n * n for n in range(1, 11)}, "cubes": {n ** 3 for n in range(1, 5)},
         "pow2no32": {2, 4, 8, 16, 64}, "pow2or37": {2, 4, 8, 16, 32, 37, 64}}
    for m in [3, 4, 5, 6, 7, 8, 9, 11, 12]:
        r["mult%d" % m] = set(range(m, 101, m))
    for m in range(2, 11):
        r["pow%d" % m] = {m ** k for k in range(1, 8) if m ** k <= 100}
    for d in range(10):
        r["ends%d" % d] = {n for n in N if n % 10 == d}
        r["contains%d" % d] = {n for n in N if str(d) in str(n)}
    return r

def test_statistic(df):
    R = _rules()
    d = df[["number_set", "target", "rating"]].copy()
    d["target"] = d["target"].astype(int)
    vals = []
    for s, g in d.groupby("number_set"):
        ex = [int(x) for x in s.split(",")]
        if len({e % 2 for e in ex}) != 1:
            continue
        lo, hi = min(ex), max(ex)
        cons = set()
        for c in R.values():
            if len(c) <= 25 and all(e in c for e in ex):
                cons |= c
        t = g["target"].to_numpy()
        m = (t % 2 != ex[0] % 2) & ((t < lo - 5) | (t > hi + 5)) & ~np.isin(t, list(cons))
        vals.append(g["rating"].to_numpy()[m])
    v = np.concatenate(vals) if vals else np.array([])
    return float(v.mean()) if len(v) else 0.0

# name: digit_overlap_unsupported_contrast
# description: Among non-example targets in no small rule (<=25 members) containing all examples, yes rate of targets sharing at least one digit character (any position) with some example minus targets sharing none; observed above null means people use surface digit similarity (e.g. 61, 19, 12 for 100,1,16) beyond the model's rules and intervals, below null means less.
def _rules():
    N = range(1, 101)
    r = {"odd": {n for n in N if n % 2}, "even": {n for n in N if n % 2 == 0},
         "primes": {n for n in N if n > 1 and all(n % a for a in range(2, int(n ** 0.5) + 1))},
         "squares": {n * n for n in range(1, 11)}, "cubes": {n ** 3 for n in range(1, 5)},
         "pow2no32": {2, 4, 8, 16, 64}, "pow2or37": {2, 4, 8, 16, 32, 37, 64}}
    for m in [3, 4, 5, 6, 7, 8, 9, 11, 12]:
        r["mult%d" % m] = set(range(m, 101, m))
    for m in range(2, 11):
        r["pow%d" % m] = {m ** k for k in range(1, 8) if m ** k <= 100}
    for d in range(10):
        r["ends%d" % d] = {n for n in N if n % 10 == d}
        r["contains%d" % d] = {n for n in N if str(d) in str(n)}
    return r

def test_statistic(df):
    R = _rules()
    d = df[["number_set", "target", "rating"]].copy()
    d["target"] = d["target"].astype(int)
    a, b = [], []
    for s, g in d.groupby("number_set"):
        ex = [int(x) for x in s.split(",")]
        small = set()
        for c in R.values():
            if len(c) <= 25 and all(e in c for e in ex):
                small |= c
        digs = set("".join(str(e) for e in ex))
        t = g["target"].to_numpy()
        r = g["rating"].to_numpy()
        ok = ~np.isin(t, ex) & ~np.isin(t, list(small))
        share = np.array([bool(set(str(x)) & digs) for x in t], dtype=bool)
        a.append(r[ok & share]); b.append(r[ok & ~share])
    a, b = np.concatenate(a), np.concatenate(b)
    if len(a) == 0 or len(b) == 0:
        return 0.0
    return float(a.mean() - b.mean())
